export class Workspace {
 constructor(client){this.c=client;this.state={page:'overview',tab:'',person:client.person,project:'',unit:client.context.yonetilen_birimler?.includes('IMALAT')?'IMALAT':client.me.birim??'',day:client.today,...period(client.today),selected:'',search:''};this.refs={IS:[],GOREV:[],ETAP:[],NESNE:[],TEZGAH:[],IZIN:[],EK_MESAI:[],SORUMLULUK:[]};this.data={};this.errors=[];this.version=0;this.draftRows=[];this.draftIndex=0;this.approvalSelection=new Set();this.onData=()=>{if(this.state.page!=='assign'){if(this.c.projects.length&&!this.c.projects.some(p=>idOf(p)===this.state.project)){this.state.project=idOf(this.c.projects[0]);void this.load();}else{this.refreshRefs();this.render();}}};this.c.addEventListener('data',this.onData);setDisplayResolver(id=>this.rawName(id));}
 dispose(){this.version++;this.c.removeEventListener('data',this.onData);}
 get page(){return this.state.page;}
 get title(){return titleCase(NAV.find(n=>n.id===this.page)?.title??'Çalışma Alanı');}
 get current(){return this.rows().find(x=>idOf(x)===this.state.selected);}
 rawName(id){const bare=String(id).split(':')[0];for(const rows of [this.c.people,this.c.units,this.c.projects,...Object.values(this.refs)]){const found=arr(rows).find(x=>idOf(x)===id||idOf(x)===bare);if(found)return found.ad??found.islem??found.is_tanimi??found.kod;}return null;}
 name(id){return id==null?'—':displayText(this.rawName(id)??label(id),key=>this.rawName(key));}
 field(key){return titleCase(fieldNames[key]??label(key));}
 can(code){
  if(this.c.readonly)return false;if(this.c.admin)return true;
  if(['NOT.YAZDIM','BILDIRIM.GORDUM','IZIN.TALEP_ETTIM','IZIN.IPTAL_ETTIM','SORUMLULUK.ITIRAZ_ETTIM','GOREV.KABUL_ETTIM','GOREV.TAMAMLADIM','GUN_SONU.GONDERDIM','MESAI.GIRDIM','MESAI.CIKTIM','IS.BASLADIM','IS.MOLA_VERDIM','IS.ARIZA_BILDIRDIM','IS.DEVAM_ETTIM','IS.TAMAMLADIM'].includes(code))return true;
  if(this.c.context.islem_izinleri?.includes(code))return true;
  if(code==='IZIN.IK_ONAYLADIM'&&this.c.roles.includes('IK'))return true;
  return this.c.manager&&!['YETKI.TANIMLADIM','MAAS.GUNCELLEDIM','MODUL.TANIMLADIM','NESNE_TURU.TANIMLADIM'].includes(code);
 }
 available(code,record){
  if(!record)return true;
  if(code==='GOREV.KABUL_ETTIM')return record.durum==='ATANDI';
  if(code==='GOREV.TAMAMLADIM')return ['ACIK','REDDEDILDI'].includes(record.durum);
  if(['GOREV.ONAYLADIM','GOREV.REDDETTIM','IS.ONAYLADIM','IS.REDDETTIM'].includes(code))return record.durum==='ONAY_BEKLIYOR';
  if(['GOREV.DEGISTIRDIM','IS.DEGISTIRDIM','GOREV.IPTAL_ETTIM','IS.IPTAL_ETTIM'].includes(code))return !['BITTI','IPTAL'].includes(record.durum);
  if(['IS.BASLADIM','IS.TAMAMLADIM','IS.MOLA_VERDIM','IS.ARIZA_BILDIRDIM','IS.DEVAM_ETTIM'].includes(code))return record.kisi===this.c.person&&this.clockAllowed(code);
  return true;
 }
 allowedPages(){if(this.c.readonly)return ['overview','projects','staffing','reports','performance'];return NAV.map(x=>x.id).filter(id=>{
  if(['settings','payroll'].includes(id))return this.c.admin;
  if(['assign','approvals','dayclose','responsibility','staffing','reports'].includes(id))return this.c.manager||['approvals','dayclose','responsibility'].includes(id)||this.c.context.islem_izinleri?.some(k=>OPERATIONS[k]?.page===id);
  if(['people','units','machines'].includes(id))return this.c.manager||this.c.roles.includes('MALIYET');return true;
 });}
 async navigate(page){if(!this.allowedPages().includes(page))page='tasks';this.state.page=page;this.state.tab='';this.state.selected='';this.state.search='';this.state.project||=idOf(this.c.projects[0]);this.state.person||=this.c.person;document.querySelectorAll('.nav-link').forEach(a=>a.classList.toggle('active',a.dataset.page===page));await this.load();}
 async query(v,h=null,g={}){try{return (await this.c.read(v,h,g,true)).deger;}catch(e){this.errors.push(e.message);return undefined;}}
 value(v,h=null,g={}){return this.c.cached(v,h,g);}
 async load(){
  const version=++this.version;this.errors=[];const s=this.state,c=this.c,range={bas:s.bas,bit:s.bit},reads=[];
  if(['overview','tasks','assign','approvals','projects','responsibility','day','dayclose','notifications'].includes(this.page))reads.push(['WEB_GOREVLER']);
  if(['overview','assign','workshop','team','day','dayclose','projects','notifications'].includes(this.page))reads.push(['WEB_ISLER']);
  if(['overview','tasks','notifications'].includes(this.page))reads.push(['BILDIRIMLER',c.person],['GUN_ISLERI',c.person]);
  if(this.page==='tasks'||this.page==='workshop'||this.page==='team')reads.push(['TELEFON']);
  if(this.page==='approvals')reads.push(['ONAY_LISTESI']);
  if(this.page==='tasks'&&s.selected)reads.push(['GOREV_AYRINTISI',s.selected]);
  if(['workshop','team'].includes(this.page)){
   const unit=s.unit||c.me.birim;reads.push(['HAVUZ',unit],['EKIP',unit]);
   for(const p of c.people.filter(x=>x.birim===unit))reads.push(['LISTE',idOf(p)]);
  }
  if(this.page==='day')reads.push(['KISININ_GUNU',s.person,{tarih:s.day}],['GUN',s.person,{gun:s.day}],['ELLE_SURELER',s.unit||c.me.birim,range]);
  if(this.page==='dayclose')reads.push(['GUN',s.person,{gun:s.day}],['GUN_ISLERI',s.person]);
  if(['projects','objects','reports'].includes(this.page)&&s.project){
   reads.push(['ETAPLAR',s.project],['PROJE_DURUM',s.project]);
   if(this.page==='projects')reads.push(['TEZGAHLAR']);
   if(this.page==='projects')reads.push(['PROJE',s.project],['PROJE',s.project,{ekip:true}],['GANTT',s.project,range],['PLAN',s.project],['PLAN',s.project,{surumler:true}],['PLAN_CAKISMALARI',s.resource||c.person,range],['NESNELER',s.project]);
   if(this.page==='objects')reads.push(['NESNELER',s.project]);
   if(this.page==='reports')reads.push(['PROJE_MALIYETI',s.project,{ay:s.bas.slice(0,7)+'-01'}],['PROJE_ISCILIGI',s.project,{...range,kirilim:'BIRIM'}],['TAHMIN_GERCEK',s.project,range]);
  }
  if(this.page==='overview')for(const p of c.projects.slice(0,20))reads.push(['PROJE_DURUM',idOf(p)]);
  if(['leaves','overtime','calendar','machines'].includes(this.page))reads.push(['WEB_KAYNAKLAR']);
  if(this.page==='responsibility')reads.push(['WEB_SORUMLULUK'],['GECIKME_RAPORU',null,{...range,kirilim:'sorumlu'}]);
  if(this.page==='staffing')reads.push(['KIM_NEREDE',null,range],['BIRIM_DOLULUGU',null,range],['SAAT_NEREYE_GITTI',null,range],['PERSONEL_DAGILIMI',null,range]);
  if(this.page==='performance')reads.push(['PERFORMANS',s.person,range],['BIRIM_PERFORMANS',s.unit||c.me.birim,range]);
  if(this.page==='payroll')reads.push(['MAAS_DAGILIMI',s.person,{ay:s.bas.slice(0,7)+'-01'}],['MAAS',s.person,{ay:s.bas.slice(0,7)+'-01'}],['SAAT_MALIYETI',s.person,{gun:s.day}]);
  if(['people','machines','assign','settings'].includes(this.page))reads.push(['TEZGAHLAR']);
  if(this.page==='people'){reads.push(['WEB_KISI',s.person]);if(c.admin)reads.push(['WEB_HESAPLAR']);}
  if(this.page==='settings')reads.push(['WEB_FIRMA']);
  if(['assign','tasks'].includes(this.page))for(const p of c.projects)reads.push(['ETAPLAR',idOf(p)]);
  this.loading=true;this.render(true);let results;try{results=await c.pageReads(reads);}finally{if(version===this.version)this.loading=false;}if(version!==this.version)return;
  this.errors=results.filter(r=>r.error).map(r=>r.error);this.refreshRefs();
  if(this.page==='logs'){this.logRows=await c.journal();this.flowRows=null;}
  if(['projects','objects'].includes(this.page)&&s.project)c.listen(['proje:'+s.project]);else c.listen();
  this.render();
 }
 refreshRefs(){const s=this.state;this.refs={...this.refs,KISI:this.c.people,BIRIM:this.c.units,PROJE:this.c.projects,TEZGAH:arr(this.value('TEZGAHLAR')),IS:arr(this.value('WEB_ISLER')),GOREV:arr(this.value('WEB_GOREVLER')),ETAP:this.c.projects.flatMap(p=>arr(this.value('ETAPLAR',idOf(p)))),NESNE:arr(this.value('NESNELER',s.project))};
  const r=this.value('WEB_KAYNAKLAR')??{},z=this.value('WEB_SORUMLULUK')??{};
  this.refs.IZIN=arr(r.izinler).map(x=>({...x,ad:this.name(x.kisi)+' · '+date(x.baslangic)+' – '+date(x.bitis)}));
  this.refs.EK_MESAI=arr(r.ek_mesai).map(x=>({...x,ad:this.name(x.kisi)+' · '+date(x.tarih)}));this.refs.BAKIM=arr(r.bakimlar).map(x=>({...x,ad:this.name(x.tezgah)+' · '+date(x.baslangic)}));this.refs.DURUS=arr(r.duruslar).map(x=>({...x,ad:x.neden}));
  this.refs.SORUMLULUK=arr(z.sorumluluklar).map(x=>({...x,kimlik:x.satir,ad:this.name(x.kimlik)+' · %'+x.yuzde}));this.refs.ITIRAZ=arr(z.itirazlar).map(x=>({...x,ad:'Sorumluluk itirazı · '+x.kimlik}));
  this.refs.GECIKME=[...this.refs.GOREV.filter(x=>x.ilk_teslim_ani).map(x=>({...x,ad:x.ad})),...arr(this.value('KISININ_GUNU',s.person,{tarih:s.day})?.kayitlar).filter(x=>x.eylem==='IS.ARIZA_BILDIRDIM')];
 }
 async formRefs(code){
  let reads;
  if(code?.startsWith('PROJE.'))reads=[];
  else if(code?.startsWith('IZIN.'))reads=code==='IZIN.TALEP_ETTIM'?[]:[['WEB_KAYNAKLAR']];
  else if(code?.startsWith('EK_MESAI.'))reads=[['WEB_KAYNAKLAR'],['WEB_ISLER'],['WEB_GOREVLER']];
  else if(code?.startsWith('NESNE.'))reads=[['NESNELER']];
  else if(['GOREV.ONAYLADIM','IS.ONAYLADIM'].includes(code))reads=[[code.startsWith('GOREV.')?'WEB_GOREVLER':'WEB_ISLER']];
  else reads=[['WEB_ISLER'],['WEB_GOREVLER'],['TEZGAHLAR'],['NESNELER'],['WEB_KAYNAKLAR'],['WEB_SORUMLULUK'],...this.c.projects.map(p=>['ETAPLAR',idOf(p)])];
  await Promise.all(reads.map(([v,h=null])=>this.c.read(v,h,{},true)));this.refreshRefs();this.refs.NESNE=arr(this.c.cached('NESNELER'))||this.refs.NESNE;return this.refs;}
 opButtons(page=this.page,record=this.current){const acts=actionsFor(page).filter(a=>this.can(a.code));const common=acts.filter(a=>!a.target&&!a.ref),context=acts.filter(a=>a.target||a.ref);return `${common.slice(0,2).map((a,i)=>button(a.title,'operation',{code:a.code},i===0?'primary':'secondary')).join('')}${common.length>2?this.more(common.slice(2)):''}${context.length?this.more(context,'Seçili Nesne İşlemleri'):''}`;}
 more(ops,title='Diğer İşlemler'){return `<div class="overflow-menu"><button type="button" class="btn" data-menu-toggle aria-haspopup="true" aria-expanded="false">${esc(title)} ▾</button><div class="menu-items" hidden>${ops.map(a=>button(a.title,'operation',{code:a.code})).join('')}</div></div>`;}
 filterSelect(key,title,rows,value,{all=false}={}){return `<label class="field"><span>${esc(title)}</span><select data-filter="${key}">${all?'<option value="">Tümü</option>':''}${rows.map(x=>`<option value="${esc(idOf(x))}" ${idOf(x)===value?'selected':''}>${esc(x.ad??idOf(x))}</option>`).join('')}</select></label>`;}
 filters(){const s=this.state,parts=[];if(['projects','objects','reports'].includes(this.page))parts.push(this.filterSelect('project','Proje',this.c.projects,s.project));
  if(['day','dayclose','performance','payroll'].includes(this.page))parts.push(this.filterSelect('person','Çalışan',this.c.people.filter(x=>this.c.admin||idOf(x)===this.c.person||this.c.context.gorulebilen_kisiler?.includes(idOf(x))),s.person));
  if(['workshop','team','day','performance'].includes(this.page))parts.push(this.filterSelect('unit','Birim',this.c.units.filter(x=>this.c.admin||idOf(x)===this.c.me.birim||this.c.context.yonetilen_birimler?.includes(idOf(x))),s.unit));
  if(['day','dayclose'].includes(this.page))parts.push(`<label class="field"><span>Gün</span><input type="date" data-filter="day" value="${esc(s.day)}"></label>`);
  if(['staffing','reports','performance','payroll','responsibility','projects','machines'].includes(this.page))parts.push(`<label class="field"><span>Başlangıç</span><input type="date" data-filter="bas" value="${esc(s.bas)}"></label><label class="field"><span>Bitiş</span><input type="date" data-filter="bit" value="${esc(s.bit)}"></label>`);
  if(this.page==='projects')parts.push(this.filterSelect('resource','Çakışma denetlenecek kaynak',[...this.c.people,...this.refs.TEZGAH],s.resource||this.c.person));
  if(this.page==='notifications')parts.push(`<label class="search-box"><input type="search" data-search placeholder="Bu ekranda ara…" aria-label="Bu ekranda ara" value="${esc(s.search)}"></label>`);return parts.length?`<div class="filter-bar">${parts.join('')}</div>`:'';
 }
 tabs(items,fallback){const selected=this.state.tab||fallback||items[0][0];return `<div class="tabs">${items.map(([id,text])=>`<button type="button" class="tab ${selected===id?'active':''}" data-action="tab" data-tab="${id}">${esc(text)}</button>`).join('')}</div>`;}
 metrics(items){return `<div class="metrics">${items.map(([title,val,note])=>`<div class="metric"><label>${esc(titleCase(title))}</label><strong>${esc(val)}</strong><small>${esc(note??'')}</small></div>`).join('')}</div>`;}
 progress(value){if(value!=null&&!Number.isFinite(Number(value)))return '<span class="muted">Henüz planlanmadı</span>';return `<div class="progress-track"><div><i style="width:${Math.max(0,Math.min(100,Number(value??0)))}%"></i></div><span>${value==null?'—':num(value)+'%'}</span></div>`;}
 render(loading=false){const main=document.querySelector('#main');if(!main)return;document.querySelector('#breadcrumb').textContent=this.title;main.innerHTML=`<div class="page-heading"><div><div class="page-eyebrow">${esc(groupTitles[this.page]??'Çalışma Alanı')}</div><h1>${esc(this.title)}</h1>${['assign','tasks','approvals','workshop','team'].includes(this.page)?'':`<p>${esc(descriptions[this.page])}</p>`}</div><div class="toolbar">${!this.c.readonly&&this.page!=='assign'?this.opButtons():''}${button('Yenile','refresh')}</div></div>${this.filters()}${loading||this.loading||this.accepting?.size?'<div class="loading-line" role="progressbar" aria-label="Bilgiler güncelleniyor"></div>':''}${this.errors.length?`<div class="notice warn">${esc([...new Set(this.errors)].join(' '))}</div>`:''}<div id="page-body">${this.body()}</div><div class="page-info"><span>${esc(date(this.c.today))}</span>${this.c.pending?`<strong>${this.c.pending} işlem gönderilmeyi bekliyor</strong>`:''}</div>`;this.bind();if(this.page==='notifications'&&this.state.search)this.search(this.state.search);}
 body(){switch(this.page){case'overview':return this.overview();case'tasks':return this.tasks();case'assign':return this.assignment();case'workshop':return this.workshop();case'approvals':return this.approvals();case'day':return this.day();case'dayclose':return this.readPanel('GUN',this.state.person,{gun:this.state.day})+this.readPanel('GUN_ISLERI',this.state.person);case'projects':return this.projects();case'objects':return this.objects();case'people':return this.people();case'units':return this.units();case'machines':return this.machines();case'calendar':return this.calendar();case'leaves':return this.leaves();case'overtime':return this.overtime();case'responsibility':return this.responsibility();case'staffing':return this.staffing();case'reports':return this.reports();case'performance':return this.performance();case'payroll':return this.payroll();case'settings':return this.settings();case'logs':return this.logs();case'notifications':return this.notifications();default:return empty();}}
 rows(){switch(this.page){case'tasks':return this.refs.GOREV.filter(x=>x.kisi===this.c.person);case'workshop':return this.refs.IS;case'approvals':return arr(this.value('ONAY_LISTESI'));case'projects':return this.c.projects;case'objects':return this.refs.NESNE;case'people':return this.c.people;case'units':return this.c.units;case'machines':return this.refs.TEZGAH;case'leaves':return this.refs.IZIN;case'overtime':return this.refs.EK_MESAI;case'responsibility':return this.refs.SORUMLULUK;default:return [];}}
 overview(){const projects=this.c.projects,me=this.refs.GOREV?.filter(x=>x.kisi===this.c.person&&x.durum!=='BITTI'&&x.durum!=='IPTAL')??[],notes=arr(this.value('BILDIRIMLER',this.c.person));return `${this.metrics([['Görülen projeler',num(projects.length),'Yetkiniz kapsamındaki projeler'],['Açık görevlerim',num(me.length),'Teslim ve kabul bekleyenler'],['Okunmamış bildirim',num(notes.filter(x=>!x.gorulme_ani).length),'Bilgi ve birim istekleri'],['Çalışma alanı',this.c.readonly?'Örnek veri':'Canlı','Telefon ve web aynı motoru kullanır']])}<div class="two-columns">${panel('Projeler',table([{label:'Proje',render:r=>`<strong>${esc(r.ad)}</strong><small>${esc(r.kod??idOf(r))}</small>`},{label:'Durum',render:r=>badge(r.durum??'ACIK')},{label:'İlerleme',render:r=>this.progress(this.value('PROJE_DURUM',idOf(r))?.yuzde)},{label:'Teslim',render:r=>date(r.teslim_tarihi??r.bitis)}],projects),button('Projeleri Aç','navigate',{page:'projects'}))}${panel('İşlerim',this.taskTable(me.slice(0,8)),button('İşlerimi Aç','navigate',{page:'tasks'}))}</div>`;}
 taskTable(rows){return table([{label:'Görev',render:r=>`<strong>${esc(r.ad)}</strong><small>${esc(this.name(r.proje))}</small>`},{label:'Teslim',render:r=>`${date(r.teslim_tarihi)}${r.teslim_saati?'<small>'+esc(r.teslim_saati)+'</small>':''}`},{label:'Zaman değeri',numeric:true,render:r=>hours(r.zaman_degeri)},{label:'Durum',render:r=>badge(r.durum)},{label:'',render:r=>button('Ayrıntı','inspect',{kind:'GOREV',id:idOf(r)},'small')}],rows,{select:true,kind:'GOREV',selected:this.state.selected});}
 tasks(){const all=this.refs.GOREV?.filter(x=>x.kisi===this.c.person)??[];const tab=this.state.tab||'open',rows=all.filter(x=>tab==='all'||tab==='open'&&!['BITTI','IPTAL'].includes(x.durum)||tab==='done'&&x.durum==='BITTI');const selected=rows.find(x=>idOf(x)===this.state.selected);return this.tabs([['open','Açık Görevler'],['done','Tamamlananlar'],['all','Bütün Görevler']])+panel('Görevlerim',`<div class="action-strip">${selected?`<strong>${esc(selected.ad)}</strong>${button('Ayrıntı ve Dosyalar','inspect',{kind:'GOREV',id:idOf(selected)},'small')}${['GOREV.KABUL_ETTIM','GOREV.TAMAMLADIM','NOT.YAZDIM'].map(code=>this.can(code)&&this.available(code,selected)?button(OPERATIONS[code].title,'operation',{code},code==='GOREV.TAMAMLADIM'?'primary small':'small'):'').join('')}`:'İşlem yapmak için bir görev seçin.'}</div>${this.taskTable(rows)}`)+`<div style="height:18px"></div>`+this.clock()+this.readPanel('GUN_ISLERI',this.c.person);}
 clock(){const p=this.value('TELEFON');if(!p?.son_hal)return '';const hal=p.son_hal,is_=p.isler?.[hal.acik_is??hal.aralik_is??p.liste?.[0]],open=['MESAI.GIRDIM','IS.BASLADIM','IS.TAMAMLADIM','IS.MOLA_VERDIM','IS.ARIZA_BILDIRDIM','IS.DEVAM_ETTIM','MESAI.CIKTIM'];return panel('Çalışmam',`<div class="work-clock"><div><strong>${esc(is_?.islem??is_?.is_tanimi??'Şu an açık iş yok')}</strong><small>${esc(is_?this.name(is_.proje):'Günün durumu')}&nbsp; ${badge(hal.durum)}</small></div><div class="toolbar">${!this.c.readonly?open.filter(c=>this.clockAllowed(c,hal,is_)).map(c=>button(OPERATIONS[c].title,'clock',{code:c,id:is_?idOf(is_):''},c==='IS.TAMAMLADIM'?'success':'secondary')).join(''):''}</div></div>`);}
 clockAllowed(code){return this.value('TELEFON')?.kapilar?.[code]===true;}
 workshop(){if(!this.c.manager)return this.clock()+panel('İş Listem',this.auto(this.value('LISTE',this.c.person)?.isler??[]));const s=this.state,pool=arr(this.value('HAVUZ',s.unit)),team=arr(this.value('EKIP',s.unit));return `<div class="pool-layout">${panel('Ekip İş Havuzu',table([{label:'İş / Parça',render:r=>`<strong>${esc(r.islem??r.is_tanimi)}</strong><small>${esc(this.name(r.proje))} · ${esc(r.parca_kodu??'')}</small>`},{label:'Tahmin',numeric:true,render:r=>r.tur==='ANLIK'?'Anlık':hours((r.tahmini_sure_dk??0)/60)},{label:'Durum',render:r=>badge(r.durum??'ACIK')},{label:'',render:r=>button('Ayrıntı','inspect',{kind:'IS',id:idOf(r)},'small')}],pool,{select:true,kind:'IS',selected:s.selected}),button('İş Tanımla','operation',{code:'IS.TANIMLADIM'},'primary'))}${panel('Çalışanların Sıralı İşleri',team.length?team.map(p=>{const list=arr(this.value('LISTE',p.kisi)?.isler);return `<section class="person-list" data-drop-person="${esc(p.kisi)}"><div class="person-list-head"><strong>${esc(p.ad??this.name(p.kisi))}</strong>${badge(p.hal?.durum)}</div>${list.length?list.map((r,i)=>`<div class="person-job" draggable="true" data-job="${esc(idOf(r))}" data-person="${esc(p.kisi)}"><span class="order">${i+1}</span><span class="job-name">${esc(r.islem??r.is_tanimi)}<small>${esc(r.parca_kodu??this.name(r.proje))}</small></span>${badge(r.durum)}<button class="text-button" data-action="job-menu" data-id="${esc(idOf(r))}" data-person="${esc(p.kisi)}">•••</button></div>`).join(''):'<div class="muted" style="font-size:11px;padding:6px">İş atamak için havuzdaki işi buraya bırakın.</div>'}</section>`;}).join(''):empty())}</div>`;}
 approvals(){const rows=arr(this.value('ONAY_LISTESI'));return '<div class="approval-list">'+panel('Onay Bekleyen İşler ve Teslimler',table([{label:'',className:'selection-col',render:r=>`<input type="checkbox" data-approve-select="${esc(idOf(r))}" aria-label="Onay için seç" ${this.approvalSelection.has(idOf(r))?'checked':''}>`},{label:'İş / Görev',render:r=>`<strong>${esc(r.ad??r.islem??r.is_tanimi??this.name(idOf(r)))}</strong><small>${esc(this.name(r.proje))}</small>`},{label:'Çalışan',render:r=>esc(this.name(r.kisi??r.tamamlayan))},{label:'Durum',render:r=>badge(r.durum??'ONAY_BEKLIYOR')},{label:'İşlemler',render:r=>{const task=this.refs.GOREV?.some(x=>idOf(x)===idOf(r));return '<div class="row-actions">'+button('İncele','inspect',{kind:task?'GOREV':'IS',id:idOf(r)},'small')+button('Onayla','quick-approve',{kind:task?'GOREV':'IS',id:idOf(r)},'success small')+button('Düzeltme İste','operation',{code:task?'GOREV.REDDETTIM':'IS.REDDETTIM',id:idOf(r),kind:task?'GOREV':'IS'},'small')+'</div>';}}],rows),button('Seçilenleri Onayla','approve-selected',{},'primary'))+'</div>';}
 day(){const s=this.state,r=this.value('KISININ_GUNU',s.person,{tarih:s.day});if(!r)return empty();const buckets=r.kovalar??{},total=Object.values(buckets).reduce((a,x)=>a+(Number(x)||0),0);return panel(this.name(s.person)+' · '+date(s.day),`<div class="panel-body"><div class="timeline">${Object.entries(buckets).filter(([,v])=>v>0).map(([k,v])=>`<div style="width:${total?100*v/total:0}%;background:${sumTypes[k]??'#98a2b3'}" title="${esc(metricLabels[k]??label(k))}: ${num(v)} dk">${v>total*.09?esc(metricLabels[k]??label(k)):''}</div>`).join('')}</div><div class="time-legend">${Object.entries(buckets).map(([k,v])=>`<span><i style="background:${sumTypes[k]??'#98a2b3'}"></i>${esc(metricLabels[k]??label(k))} <strong>${hours(Number(v)/60)}</strong></span>`).join('')}</div></div>${this.auto(r.araliklar??r.zaman_cizelgesi??r.satirlar??[],{select:false})}<div class="panel-head"><h2>Saat İşlemleri</h2></div>${table([{label:'Saat',render:x=>time(x.an)},{label:'İşlem',render:x=>esc(OPERATIONS[x.eylem]?.title??label(x.eylem))},{label:'İşlem Ayrıntısı',render:x=>`<span>${esc(this.name(x.hedef??x.is??x.gorev))}</span>`},{label:'',render:x=>button('Geçersiz Say','operation',{code:'KAYIT.GECERSIZ_SAYDIM',id:x.kimlik},'small')}],r.kayitlar??[])}`)+this.readPanel('GUN',s.person,{gun:s.day});}
 projects(){const s=this.state,p=this.c.projects.find(x=>idOf(x)===s.project),o=this.value('PROJE_DURUM',s.project)??{},es=arr(this.value('ETAPLAR',s.project));if(!p)return empty();const tab=s.tab||'status';const head=this.metrics([['Proje ilerlemesi',o.yuzde==null||!Number.isFinite(Number(o.yuzde))?'Plan Bekliyor':num(o.yuzde)+'%','Onaylanan işlerin planlanan emeği'],['Harcanan emek',hours(o.harcanan_emek??o.harcanan_saat),'Gerçekleşen çalışma'],['Hedef emek',hours(o.hedef??o.hedef_saat),'Etapların hedef toplamı'],['Teslim',date(p.teslim_tarihi??p.bitis),label(p.durum)]]);let body='';
  if(tab==='status'||tab==='stages')body=panel('Etaplar',table([{label:'Etap',render:r=>`<strong>${esc(r.ad)}</strong><small>${esc(this.name(r.birim))}</small>`},{label:'Sorumlu',render:r=>esc(this.name(r.sorumlu))},{label:'Başlangıç',render:r=>date(r.baslangic)},{label:'Bitiş',render:r=>date(r.bitis)},{label:'Hedef',numeric:true,render:r=>hours(r.hedef_saat??r.hedef)},{label:'İlerleme',render:r=>this.progress(o.etaplar?.[idOf(r)]?.yuzde??r.yuzde)},{label:'Bütçe tüketimi',numeric:true,render:r=>{const v=o.etaplar?.[idOf(r)]?.butce_tuketimi??r.butce_tuketimi;return typeof v==='number'?num(v)+'%':'—';}},{label:'İşlemler',render:r=>this.c.readonly?'':button('Düzenle','operation',{code:'ETAP.DEGISTIRDIM',id:idOf(r),kind:'ETAP'},'small')}],es),!this.c.readonly&&this.can('ETAP.TANIMLADIM')?button('Etap Ekle','operation',{code:'ETAP.TANIMLADIM'},'primary small'):'');
  if(tab==='plan')body=this.gantt(this.value('GANTT',s.project,{bas:s.bas,bit:s.bit}))+this.readPanel('PLAN',s.project)+this.readPanel('PLAN_CAKISMALARI',s.resource||this.c.person,{bas:s.bas,bit:s.bit});
  if(tab==='team')body=panel('Proje Ekibi ve Erişim',`<div class="panel-body">${details(p,[['sorumlu','Proje Sorumlusu',x=>esc(this.name(x))]])}<div class="notice">Departmanlar projeye etaplarıyla dahil edilir. İş verilen kişi, ilgili proje ekibine kendiliğinden katılır.</div>${this.opButtons('projects',p)}</div>${table([{label:'Etap / Departman',render:r=>esc(r.ad)+'<small>'+esc(this.name(r.birim))+'</small>'},{label:'Sorumlu',render:r=>esc(this.name(r.sorumlu))}],es)}`);
  if(tab==='jobs')body=panel('Projenin Görevleri',this.taskTable((this.refs.GOREV??[]).filter(x=>x.proje===s.project)))+panel('Atölye İşleri',this.auto((this.refs.IS??[]).filter(x=>x.proje===s.project)));
  if(tab==='cancelled')body=panel('İptal Edilen İşlerin Emeği',this.auto(o.iptal_edilenler));
  if(tab==='objects')body=this.objects();
  return head+this.tabs([['status','Proje Durumu'],['stages','Etaplar'],['plan','Plan ve Gerçekleşen'],['team','Proje Ekibi'],['jobs','İşler ve Görevler'],['objects','Parçalar ve Belgeler'],['cancelled','İptal Edilenler']],'status')+`<div class="stack">${body}</div>`;
 }
 objects(){const rows=this.refs.NESNE??[];return panel('Nesneler',table([{label:'Kod / Nesne',render:r=>`<strong>${esc(r.kod??r.ad)}</strong><small>${esc(r.ad)}</small>`},{label:'Tür',render:r=>esc(this.name(r.tur))},{label:'Aşama',render:r=>badge(r.asama)},{label:'Sorumlu',render:r=>esc(this.name(r.sorumlu))},{label:'İşlemler',render:r=>button('Ayrıntı ve Belgeler','inspect',{kind:'NESNE',id:idOf(r)},'small')}],rows,{select:true,kind:'NESNE',selected:this.state.selected}),!this.c.readonly?button('Nesne Aç','operation',{code:'NESNE.ACTIM'},'primary small'):'');}
 people(){return panel('Çalışanlar',table([{label:'Çalışan',render:r=>`<strong>${esc(r.ad)}</strong><small>${esc(idOf(r))}</small>`},{label:'Birim',render:r=>esc(this.name(r.birim))},{label:'Çalışma',render:r=>esc(label(r.yaka))},{label:'Roller',render:r=>(r.roller??[]).map(x=>`<span class="badge">${esc(label(x))}</span>`).join(' ')},{label:'Durum',render:r=>badge(r.aktif?'ACIK':'KAPALI')},{label:'İşlemler',render:r=>button('Ayrıntı','inspect',{kind:'KISI',id:idOf(r)},'small')}],this.c.people,{select:true,kind:'KISI',selected:this.state.selected}))+`<div style="height:18px"></div>`+(this.c.admin?panel('Giriş Hesapları',table([{label:'Çalışan',key:'ad'},{label:'Hesap',render:r=>r.hesap_var?'Açık':'Henüz açılmadı'},{label:'İşlemler',render:r=>button(r.hesap_var?'Şifre Sıfırla':'Hesap Aç','account-admin',{id:r.kisi,mode:r.hesap_var?'sifirla':'ac'},'small')}],arr(this.value('WEB_HESAPLAR')))):'');}
 units(){return panel('Birimler',table([{label:'Birim',render:r=>`<strong>${esc(r.ad)}</strong><small>${esc(idOf(r))}</small>`},{label:'Üst birim',render:r=>esc(this.name(r.ust??r.ust_birim))},{label:'Sorumlu',render:r=>esc(this.name(r.basi))},{label:'Mesai',render:r=>r.takvim?esc((r.takvim.mesai_baslangic??'')+' – '+(r.takvim.mesai_bitis??'')):'Firma takvimi'},{label:'',render:r=>button('Düzenle','operation',{code:'BIRIM.TANIMLADIM',id:idOf(r),kind:'BIRIM'},'small')}],this.c.units,{select:true,kind:'BIRIM',selected:this.state.selected}));}
 machines(){const rows=this.refs.TEZGAH??[],r=this.value('WEB_KAYNAKLAR')??{};return `<div class="stack">${panel('Tezgâhlar',table([{label:'Tezgâh',render:x=>`<strong>${esc(x.ad)}</strong><small>${esc(idOf(x))}</small>`},{label:'Birim',render:x=>esc(this.name(x.birim))},{label:'Durum',render:x=>badge(x.aktif?'ACIK':'KAPALI')},{label:'İşlemler',render:x=>button('Kullanım ve Takvim','machine-detail',{id:idOf(x)},'small')}],rows,{select:true,kind:'TEZGAH',selected:this.state.selected}))}${panel('Planlı Bakımlar',this.auto(r.bakimlar))}${panel('Tezgâh Duruşları',this.auto(r.tezgah_duruslari))}</div>`;}
 calendar(){const r=this.value('WEB_KAYNAKLAR')??{};return `<div class="stack"><div class="equal-columns">${panel('Firma ve Birim Mesaisi',this.auto(r.takvim))}${panel('Tatiller',this.auto(r.tatiller))}</div>${panel('Özel Günler',this.auto(r.gun_tanimlari))}${panel('Toplu Duruşlar',table([{label:'Neden',key:'neden'},{label:'Kapsam',render:x=>esc(Array.isArray(x.kapsam)?x.kapsam.map(x=>this.name(x)).join(', '):label(x.kapsam))},{label:'Başlangıç',render:x=>date(x.baslangic)+' '+time(x.baslangic)},{label:'Bitiş',render:x=>x.bitis?date(x.bitis)+' '+time(x.bitis):'Devam ediyor'},{label:'',render:x=>!x.bitis?button('Duruşu Bitir','operation',{code:'DURUS.BITTI',id:idOf(x),kind:'DURUS'},'small'):''}],arr(r.duruslar)))}</div>`;}
 leaves(){return panel('İzin Talepleri',table([{label:'Çalışan',render:r=>esc(this.name(r.kisi))},{label:'İzin türü',render:r=>esc(this.name(r.tur))},{label:'Başlangıç',render:r=>date(r.baslangic)+' '+time(r.baslangic)},{label:'Bitiş',render:r=>date(r.bitis)+' '+time(r.bitis)},{label:'Durum',render:r=>badge(r.durum)},{label:'Gerekçe',key:'gerekce'}],this.refs.IZIN??[],{select:true,kind:'IZIN',selected:this.state.selected}));}
 overtime(){return panel('Planlanan ve Onaylanan Ek Mesai',table([{label:'Çalışan',render:r=>esc(this.name(r.kisi))},{label:'Tarih',render:r=>date(r.tarih)},{label:'Başlangıç',key:'baslangic'},{label:'Bitiş',key:'bitis'},{label:'Açıklama',key:'aciklama'},{label:'Durum',render:r=>badge(r.iptal?'IPTAL':r.damga?'ONAYLI':'ACIK')}],this.refs.EK_MESAI??[],{select:true,kind:'EK_MESAI',selected:this.state.selected}));}
 responsibility(){return `<div class="stack">${panel('Sorumluluk Dağılımı',table([{label:'Sorumlu',render:r=>esc(r.ad??this.name(r.kimlik))},{label:'Kaynak',render:r=>esc(label(r.kaynak_turu))},{label:'Pay',numeric:true,render:r=>'%'+num(r.yuzde)},{label:'Doğrulama',render:r=>badge(r.dogrulandi?'ONAYLI':'BEKLIYOR')},{label:'İtiraz',render:r=>r.itirazda?badge('BEKLIYOR'):'—'}],this.refs.SORUMLULUK??[],{select:true,kind:'SORUMLULUK',selected:this.state.selected}))}${this.readPanel('GECIKME_RAPORU',null,{bas:this.state.bas,bit:this.state.bit,kirilim:'sorumlu'})}</div>`;}
 staffing(){const range={bas:this.state.bas,bit:this.state.bit};return `<div class="stack">${this.readPanel('KIM_NEREDE',null,range)}<div class="equal-columns">${this.readPanel('BIRIM_DOLULUGU',null,range)}${this.readPanel('PERSONEL_DAGILIMI',null,range)}</div>${this.readPanel('SAAT_NEREYE_GITTI',null,range)}</div>`;}
 reports(){const s=this.state,range={bas:s.bas,bit:s.bit};return `<div class="stack">${this.readPanel('PROJE_MALIYETI',s.project,{ay:s.bas.slice(0,7)+'-01'})}${this.readPanel('PROJE_ISCILIGI',s.project,{...range,kirilim:'BIRIM'})}${this.readPanel('TAHMIN_GERCEK',s.project,range)}</div>`;}
 performance(){const s=this.state,p=this.value('PERFORMANS',s.person,{bas:s.bas,bit:s.bit});if(!p)return empty();return this.metrics([['Zaman',p.teslim!=null?`${num(p.zamaninda)} / ${num(p.teslim)}`:'—','Zamanında teslim'],['Kalite',num(p.kalite_ret??0),'Doğrulanmış geri dönüşler'],['Çözüm',p.cozum_saat!=null?hours(p.cozum_saat):'—','Sorun kaynaklı görevler'],['Katkı',hours(p.katki_saat??0),'Proje dışı işler']])+`<div class="stack">${panel(this.name(s.person)+' · Adil Performans',this.auto(p))}${this.readPanel('BIRIM_PERFORMANS',s.unit||this.c.me.birim,{bas:s.bas,bit:s.bit})}</div>`;}
 payroll(){const s=this.state,g={ay:s.bas.slice(0,7)+'-01'};return `<div class="stack">${this.readPanel('MAAS_DAGILIMI',s.person,g)}<div class="equal-columns">${this.readPanel('MAAS',s.person,g)}${this.readPanel('SAAT_MALIYETI',s.person,{gun:s.day})}</div></div>`;}
 settings(){const r=this.value('WEB_FIRMA')??{},tab=this.state.tab||'rules';const tabs=[['rules','Firma Kuralları'],['authority','Yetkiler'],['lists','Seçenekler'],['types','Nesne Türleri'],['modules','Modüller'],['routing','Birim İstekleri']];const key={rules:'ayarlar',authority:'yetkiler',lists:'kodlar',types:'nesne_turleri',modules:'moduller',routing:'yonlendirme'}[tab];return this.tabs(tabs,'rules')+panel(tabs.find(x=>x[0]===tab)?.[1]??'Firma Kuralları',this.auto(r[key]))+`<div class="notice" style="margin-top:16px">İşlem yetkisi sunucuda denetlenir. Firma ayarları geçerlilik tarihleriyle uygulanır; geçmiş işlemler korunur.</div>`;}
 logs(){const tab=this.state.tab||'flow';return this.tabs([['flow','Canlı Olay Akışı'],['local','Bu Bilgisayarın İşlemleri'],...(this.c.admin?[['review','İnceleme Bekleyenler']]:[])],'flow')+(tab==='flow'?this.flowRows?panel('Olaylar',table([{label:'Saat',render:r=>date(r.an)+' '+time(r.an)},{label:'Kim',render:r=>esc(r.ad??this.name(r.kim))},{label:'İşlem',render:r=>esc(OPERATIONS[r.eylem]?.title??label(r.eylem))},{label:'Nesne',render:r=>esc(r.hedef_adlari?.join(', ')??r.neyin_ustunde?.map(x=>this.name(x.kimlik)).join(', ')??'')},{label:'Cihaz',key:'cihaz'}],this.flowRows.olaylar??[])):empty('Olay akışı bu ortamda kapalı','Bu bilgisayarın kendi işlem geçmişini diğer sekmeden görebilirsiniz.'):tab==='local'?panel('Bu Bilgisayarın Günlüğü',table([{label:'An',render:r=>date(r.olay?.oldugu_an)+' '+time(r.olay?.oldugu_an)},{label:'İşlem',render:r=>esc(OPERATIONS[r.olay?.eylem_kodu]?.title??label(r.olay?.eylem_kodu))},{label:'Durum',render:r=>badge(r.durum)},{label:'Sonuç',render:r=>esc(r.sonuc?.kod??'—')},{label:'',render:r=>r.durum==='GONDERILEMEDI'?button('Aynı İşlemi Yeniden Gönder','retry-management',{id:r.olay.olay_kimligi},'small'):''}],this.logRows??[])):this.readPanel('SUPHELILER'));}
 notifications(){const rows=arr(this.value('BILDIRIMLER',this.c.person));return panel('Bildirimler',rows.length?rows.map(r=>{const content=notificationContent(r,id=>this.name(id),[...this.refs.GOREV,...this.refs.IS]),id=notificationId(r);return `<div class="notification ${r.gorulme_ani?'':'unread'}"><span class="status-dot ${r.gorulme_ani?'offline':''}" style="margin-top:8px"></span><div class="notification-copy"><strong>${esc(content.title)}</strong><p>${esc(content.text)}</p><small>${date(r.an??r.olusan_an)} ${time(r.an??r.olusan_an)}</small></div>${r.gorulme_ani?'<span class="notification-seen">Görüldü</span>':id?button('Görüldü','seen',{id},'small'):''}</div>`;}).join(''):empty('Yeni bildirim yok','İş ve proje güncellemeleri burada görünür.'));}
 renderValue(value,key=''){
  if(value==null)return '<span class="muted">—</span>';if(typeof value==='boolean')return value?'Evet':'Hayır';if(key==='durum'||key==='asama')return badge(value);
  if(typeof value==='number')return /tutar|maliyet|prim|butce|maas/.test(key)?money(value):num(value,2);
  if(typeof value==='string'){if(value.startsWith('F-')&&['dosyalar','girdi_dosyalari','dosya_kimligi'].includes(key))return button('Dosyayı Aç','file',{id:value},'small');if(/^\d{4}-\d\d-\d\d/.test(value))return date(value)+(value.includes('T')?' '+time(value):'');if(/^-?\d+\.\d+$/.test(value)&&/tutar|maliyet|prim|butce|maas/.test(key))return money(value);return esc(this.name(value));}
  if(Array.isArray(value))return value.length?value.map(x=>typeof x==='object'?this.renderValue(x):this.renderValue(x,key)).join('<br>'):'—';
  return Object.entries(value).filter(([k])=>!['brut_maas','kimlik','doguran_olay','son_olay','kural_versiyonu','olaylar','kisi_gecmisi','surum','ozet_surumu','olay','icerik','son_hesap_ani','hesap_ani','neyin_ustunde','gecmis'].includes(k)).map(([k,v])=>`<div class="value-line"><span class="muted">${esc(this.field(k))}:</span> ${this.renderValue(v,k)}</div>`).join('');
 }
 auto(data,{select=false,kind=''}={}){
  if(data==null)return empty();if(typeof data!=='object')return `<div class="panel-body">${this.renderValue(data)}</div>`;
  const rows=Array.isArray(data)?data:undefined;
  if(rows){if(!rows.length)return empty();if(rows.every(x=>typeof x!=='object'))return `<div class="panel-body">${rows.map(x=>this.renderValue(x)).join('<br>')}</div>`;
   const keys=[...new Set(rows.flatMap(x=>Object.keys(x??{})))].filter(k=>!['brut_maas','kimlik','doguran_olay','son_olay','kural_versiyonu','olaylar','kisi_gecmisi','surum','ozet_surumu','olay','gecmis','_olay','_gecerli_baslangic','_kabul_no'].includes(k));
   const cols=keys.slice(0,10).map(k=>({label:this.field(k),render:r=>this.renderValue(r?.[k],k),numeric:['saat','tutar','tahmin','gercek','fark','pay','yuzde'].includes(k)}));return table(cols,rows,{select,kind,selected:this.state.selected});
  }
  if(data.satirlar&&Array.isArray(data.satirlar))return this.auto(data.satirlar)+Object.entries(data).filter(([k])=>k!=='satirlar').map(([k,v])=>`<div class="feedback-note"><strong>${esc(this.field(k))}:</strong> ${this.renderValue(v,k)}</div>`).join('');
  return `<div class="panel-body"><dl class="detail-list">${Object.entries(data).filter(([k])=>!['brut_maas','kimlik','doguran_olay','son_olay','kural_versiyonu','olaylar','kisi_gecmisi','surum','ozet_surumu','gecmis','olay','an'].includes(k)).map(([k,v])=>`<div><dt>${esc(this.field(k))}</dt><dd>${this.renderValue(v,k)}</dd></div>`).join('')}</dl></div>`;
 }
 readPanel(v,h=null,g={},title){return panel(title??readLabels[v]??this.field(v),this.auto(this.value(v,h,g)));}
 gantt(value){
  const rows=arr(value?.satirlar??value);if(!rows.length)return panel('Plan ve Gerçekleşen',empty('Plan tarihleri henüz girilmedi','İş veya görev için plan tarihi verildiğinde bu çizelgede görünür.'));
  const now=new Date(Date.now()+(this.c.offset??0)).toISOString();
  const dates=rows.flatMap(r=>[r.planlanan_baslangic,r.planlanan_bitis,r.gerceklesen_baslangic,r.gerceklesen_bitis??(r.gerceklesen_baslangic?now:null)]).filter(Boolean).map(Date.parse).filter(Number.isFinite);
  const min=Math.min(...dates),max=Math.max(...dates),span=max-min||86400000;
  const bar=(start,end,css)=>{const a=Date.parse(start),b=Date.parse(end);return Number.isFinite(a)&&Number.isFinite(b)?`<i class="gantt-bar ${css}" style="left:${100*(a-min)/span}%;width:${Math.max(.5,100*(b-a)/span)}%" title="${esc(date(start)+' '+time(start)+' – '+date(end)+' '+time(end))}"></i>`:'';};
  return panel('Plan ve Gerçekleşen',`<div class="time-legend" style="padding:14px 16px"><span><i style="background:#6689d9"></i>Plan</span><span><i style="background:#38a877"></i>Gerçekleşen</span></div><div class="gantt"><table class="gantt-table"><tbody>${rows.map(r=>`<tr><td class="gantt-label"><strong>${esc(r.ad??this.name(idOf(r)))}</strong><small style="display:block;margin-top:4px">${date(r.planlanan_baslangic)} – ${date(r.planlanan_bitis)}</small></td><td><div class="gantt-track">${bar(r.planlanan_baslangic,r.planlanan_bitis,'plan')}${bar(r.gerceklesen_baslangic,r.gerceklesen_bitis??now,'actual')}</div></td><td>${this.progress(r.ilerleme)}${r.sapma?'<small>'+esc(label(r.sapma.tur))+'</small>':''}</td></tr>`).join('')}</tbody></table></div>`);
 }
 // Atama, ayrıntı ve etkileşimler aşağıdaki yöntemlerde tanımlanır.
 assignment(){return '<div id="assignment-host"></div>';}
 bind(){this.bindCommon();if(this.page==='assign')this.bindAssignment();if(this.page==='workshop')this.bindDrag();}
 bindCommon(){const main=document.querySelector('#main');main.querySelectorAll('[data-approve-select]').forEach(el=>el.onchange=()=>el.checked?this.approvalSelection.add(el.dataset.approveSelect):this.approvalSelection.delete(el.dataset.approveSelect));main.querySelectorAll('[data-filter]').forEach(el=>el.onchange=()=>{this.state[el.dataset.filter]=el.value;this.state.selected='';void this.load();});main.querySelector('[data-search]')?.addEventListener('input',e=>{this.state.search=e.target.value;this.search(e.target.value);});main.onclick=e=>{const el=e.target.closest('[data-action]');if(el)void this.action(el,e);};main.onkeydown=e=>{if(e.key==='Enter'&&e.target.matches('tr[data-action]'))e.target.click();};}
 search(q){q=q.toLocaleLowerCase('tr-TR');document.querySelectorAll('#page-body tbody tr').forEach(tr=>tr.hidden=!!q&&!tr.textContent.toLocaleLowerCase('tr-TR').includes(q));}
 async action(el,e){try{switch(el.dataset.action){case'retry-management':await this.retryManagement(el.dataset.id);return;case'new-from':await this.newFrom(el.dataset.kind,el.dataset.id,true);return;case'approve-selected':await this.approveSelected();return;case'account-admin':await this.accountAdmin(el.dataset.id,el.dataset.mode);return;case'file':await this.openFile(el.dataset.id);return;case'navigate':location.hash=el.dataset.page;return;case'refresh':await this.load();return;case'tab':this.state.tab=el.dataset.tab;this.render();return;case'select-row':this.state.selected=el.dataset.id;this.selectedKind=el.dataset.kind;this.render();return;case'operation':await this.operation(el.dataset.code,el.dataset.id,el.dataset.kind);return;case'inspect':await this.inspect(el.dataset.kind,el.dataset.id);return;case'quick-approve':await this.operation(el.dataset.kind==='GOREV'?'GOREV.ONAYLADIM':'IS.ONAYLADIM',el.dataset.id,el.dataset.kind);return;case'clock':await this.operation(el.dataset.code,el.dataset.id,'IS');return;case'job-menu':await this.jobMenu(el.dataset.id,el.dataset.person);return;case'machine-detail':await this.machineDetail(el.dataset.id);return;case'seen':if(el.disabled)return;el.disabled=true;try{await this.c.confirmed('BILDIRIM.GORDUM',{bildirimler:[el.dataset.id]});await this.load();}finally{if(el.isConnected)el.disabled=false;}return;case'assign-add':this.draftRows.push(this.newTask());this.draftIndex=this.draftRows.length-1;this.bindAssignment();return;case'assign-select':this.draftIndex=Number(el.dataset.index);this.bindAssignment();return;case'assign-copy':{const at=this.draftIndex+1;this.adjustDraftLinks(at,1);this.draftRows.splice(at,0,structuredClone(this.draftRows[this.draftIndex]));this.draftIndex=at;this.bindAssignment();return;}case'assign-remove':if(this.draftRows.length>1){const at=this.draftIndex;this.draftRows.splice(at,1);this.adjustDraftLinks(at,-1);}else this.draftRows=[];this.draftIndex=Math.min(this.draftIndex,this.draftRows.length-1);this.bindAssignment();return;case'assign-review':await this.reviewAssignment();return;}}catch(ex){toast(ex.message,true);}}
 async operation(code,id,kind){await this.formRefs(code);let record=id?(this.refs[kind??OPERATIONS[code]?.target??OPERATIONS[code]?.ref]??[]).find(x=>idOf(x)===id):this.current;if(!record&&id)record={kimlik:id};const defaults={};if(this.state.project&&['ETAP.TANIMLADIM','NESNE.ACTIM','PLAN.ONAYLADIM','PROJE.ERISIM_VERDIM','PROJE.ERISIM_KALDIRDIM'].includes(code))defaults.proje=this.state.project;if(code==='KAYIT.GECERSIZ_SAYDIM'&&id)defaults.hedef=id;if(code.startsWith('GUN_SONU.'))Object.assign(defaults,{kisi:this.state.person,gun:this.state.day});if(code==='BIRIM.TANIMLADIM'&&record)Object.assign(defaults,{kod:idOf(record),ad:record.ad,basi:record.basi,ust_birim:record.ust??record.ust_birim,tur:record.tur??'MASA_BASI'});if(code==='IS.TANIMLADIM')defaults.isler=[{islem:'',birim:this.state.unit,nereye:'PROJE',tur:'SURELI',tahmini_sure_dk:60,onay_gerekli:true,onay_beklet:false}];return await openOperation(this.c,code,{record,refs:this.refs,defaults,actingFor:code==='IS.SURE_EKLEDIM'?this.state.person:null,onDone:async result=>{await this.load();if(operationComplete(result)&&['GOREV.ONAYLADIM','IS.ONAYLADIM'].includes(code)&&record)await this.followup([{kind:code.split('.')[0],record}]);}});}
 async retryManagement(id){
  const entry=(await this.c.journal()).find(x=>x.olay.olay_kimligi===id);if(!entry)return;
  const d=modal('Bekleyen İşlemi Gönder',`<p style="line-height:1.7;margin-bottom:16px">${esc(OPERATIONS[entry.olay.eylem_kodu]?.title)} aynı işlem kimliğiyle yeniden gönderilecek. Sunucu önceki gönderimi aldıysa işlem tekrarlanmaz.</p><form class="stack"><div class="form-error"></div>${entry.hassas_tur?'<label class="field"><span>Tutar (₺)</span><input name="amount" type="number" min="0" step="0.01" required></label>':''}<button class="btn primary" type="submit">Yeniden Gönder</button></form>`);
  d.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button');try{b.disabled=true;const g=entry.olay.girdiler,sensitive=entry.hassas_tur?{nesne_tur:this.c.people.some(x=>idOf(x)===g.kisi)?'KISI':'TEZGAH',nesne_kimlik:g.kisi,tur:entry.hassas_tur,tutar:f.amount.value,gecerli_baslangic:g.gecerli_baslangic}:null;const result=await this.c.retryManagement(id,sensitive);d.close();toast(operationMessage(result),operationTone(result));try{await this.load();}catch{toast(operationMessage({...result,ekran_bekliyor:true}),'info');}}catch(error){f.querySelector('.form-error').textContent=error.message;b.disabled=false;}};
 }
 async newFrom(kind,id,change=false){
  await this.formRefs();const source=this.refs[kind]?.find(r=>idOf(r)===id);if(!source)return;
  const files=(await this.c.read('WEB_DOSYALAR',id,{tur:kind},true)).deger??[];
  const schema=this.c.schemas[kind==='IS'?'IS.TANIMLADIM':'GOREV.ATADIM'].girdi_semasi.properties[kind==='IS'?'isler':'gorevler'].items;
  const row={...this.newTask(),...cleanValue(source,schema),olcum:kind==='IS'?'SAAT':'ZAMAN',ad:(change?'Değişiklik: ':'Devam: ')+(source.ad??source.islem??''),teslim_tarihi:this.c.today,girdi_dosyalari:files.map(idOf)};
  if(row.nereye==='PROJE'&&!row.etap)row.etap=null;
  if(kind==='IS'){row.zaman_degeri=Math.max(1,Math.ceil((source.tahmini_sure_dk??60)/60));row.birim=source.birim;}
  row.on_kosul=change?source.on_kosul??source.on_isler??[]:[id];
  if(change)row.degisiklik={kaynak:id,neden:'MUSTERI'};else delete row.degisiklik;
  this.draftRows.push(row);this.draftIndex=this.draftRows.length-1;
  if(location.hash==='#assign')await this.navigate('assign');else location.hash='assign';
 }
 async followup(items){
  if(!items.length)return;
  const d=modal('Onaylanan İşlerin Devamı',`<p class="muted" style="margin-bottom:16px">Sonraki işi olanları işaretleyin. Proje, parça, dosyalar ve tamamlanan ön iş atama formuna gelir.</p>${table([{label:'Sonraki iş',render:r=>`<input type="checkbox" data-follow="${esc(idOf(r.record))}" aria-label="Devam işi tanımla">`},{label:'Onaylanan iş',render:r=>esc(r.record.ad??r.record.islem)},{label:'Çalışan',render:r=>esc(this.name(r.record.kisi))}],items)}<div class="form-footer"><button class="btn" data-skip>Atla</button><button class="btn primary" data-continue>Devam Et</button></div>`,{wide:true});
  d.querySelector('[data-skip]').onclick=()=>d.close();d.querySelector('[data-continue]').onclick=async()=>{const ids=[...d.querySelectorAll('[data-follow]:checked')].map(e=>e.dataset.follow);d.close();for(const item of items.filter(r=>ids.includes(idOf(r.record))))await this.newFrom(item.kind,idOf(item.record));};
 }
 async approveSelected(){
  const rows=arr(this.value('ONAY_LISTESI')).filter(r=>this.approvalSelection.has(idOf(r)));if(!rows.length)throw new Error('Önce onaylayacağınız işleri işaretleyin.');
  const done=[];try{for(const record of rows){const kind=this.refs.GOREV.some(x=>idOf(x)===idOf(record))?'GOREV':'IS';await this.c.write(kind+'.ONAYLADIM',{},[{tur:kind,kimlik:idOf(record)}]);done.push({kind,record});this.approvalSelection.delete(idOf(record));}}finally{await this.load();if(done.length)await this.followup(done);}
 }
 async accountAdmin(person,mode){
  if(this.c.config?.ortak_test)throw new Error('Hesap açma ve şifre sıfırlama bu paylaşımda açık değil. Mustafa’nın verdiği hazır profilleri kullanın.');
  const d=modal((mode==='ac'?'Hesap Aç':'Şifre Sıfırla')+' · '+this.name(person),'<form class="stack"><div class="form-error"></div><label class="field"><span>Yeni şifre · 6 rakam</span><input name="password" type="password" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="new-password" required></label><label class="field"><span>Şifreyi tekrar girin</span><input name="again" type="password" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="new-password" required></label><button class="btn primary" type="submit">Uygula</button></form>');
  d.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button');try{
   if(f.password.value!==f.again.value)throw new Error('İki şifre aynı olmalı.');b.disabled=true;
   await this.c.refreshSession();const response=await fetch('/irp/hesap',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+this.c.session.access_token},body:JSON.stringify({islem:mode,kisi:person,sifre:f.password.value})});
   let result;try{result=await response.json();}catch{throw new Error('Hesap yönetimi sunucusu açık değil. Çalışma alanını baslat.command ile açın.');}
   if(!response.ok)throw new Error(result.message??'Hesap işlemi tamamlanamadı.');f.reset();d.close();toast('Giriş hesabı güncellendi.');await this.load();
  }catch(error){f.querySelector('.form-error').textContent=error.message;b.disabled=false;}};
 }
 async openFile(id){const win=window.open('about:blank','_blank');try{const url=await this.c.fileUrl(id);if(win){win.opener=null;win.location=url;}}catch(e){win?.close();toast(e.message,true);}}
 async inspect(kind,id){await this.formRefs();const r=(this.refs[kind]??[]).find(x=>idOf(x)===id);if(!r)return;let body=this.auto(r);if(['GOREV','IS','NESNE','PROJE'].includes(kind)){const [files,notes]=await Promise.all([this.c.read('WEB_DOSYALAR',id,{tur:kind},true),this.c.read('WEB_NOTLAR',id,{tur:kind},true)]);body+=panel('Dosyalar',table([{label:'Dosya',key:'ad'},{label:'',render:f=>button('Aç','file',{id:idOf(f)},'small')}],files.deger??[]))+panel('Notlar ve İstekler',this.auto(notes.deger));}if(kind==='NESNE'){const [versions,current]=await Promise.all([this.c.read('SURUMLER',id,{},true),this.c.read('GECERLI_SURUM',id,{},true)]);body+=`<h3 style="margin:18px 0 10px">Geçerli Belge Sürümü</h3>${this.auto(current.deger)}<h3 style="margin:18px 0 10px">Sürüm Geçmişi</h3>${this.auto(versions.deger)}`;}const operations=Object.values(OPERATIONS).filter(a=>this.can(a.code)&&this.available(a.code,r)&&(a.target===kind||a.ref===kind));if(['GOREV','IS','NESNE','PROJE'].includes(kind)&&this.can('NOT.YAZDIM'))operations.push(OPERATIONS['NOT.YAZDIM']);body+=`<div class="form-footer">${['GOREV','IS'].includes(kind)&&this.can(kind==='GOREV'?'GOREV.ATADIM':'IS.TANIMLADIM')?button('Değişiklik','new-from',{kind,id},'primary'):''}${operations.map(a=>button(a.title,'detail-op',{code:a.code})).join('')}</div>`;const d=modal(r.ad??r.islem??r.is_tanimi??this.name(id),body,{wide:true});d.querySelector('[data-action=new-from]')?.addEventListener('click',()=>{d.close();void this.newFrom(kind,id,true);});d.querySelectorAll('[data-action=file]').forEach(b=>b.onclick=()=>this.openFile(b.dataset.id));d.querySelectorAll('[data-action=detail-op]').forEach(b=>b.onclick=()=>{d.close();void this.operation(b.dataset.code,id,kind);});return d;}
 async machineDetail(id){const s=this.state,g={bas:s.bas,bit:s.bit},r=this.refs.TEZGAH.find(x=>idOf(x)===id);await Promise.allSettled([['TEZGAH_GOSTERGESI',g],['TEZGAH_UYGUNLUK',g],['TEZGAH_UCRETI',{gun:s.day}]].map(([v,g])=>this.c.read(v,id,g,true)));const d=modal(r?.ad??id,this.readPanel('TEZGAH_GOSTERGESI',id,g)+this.readPanel('TEZGAH_UYGUNLUK',id,g)+(this.c.admin||this.c.roles.includes('MALIYET')?this.readPanel('TEZGAH_UCRETI',id,{gun:s.day}):'')+`<div class="form-footer">${actionsFor('machines').filter(a=>this.can(a.code)).map(a=>button(a.title,'machine-op',{code:a.code})).join('')}</div>`,{wide:true});d.querySelectorAll('[data-action=machine-op]').forEach(b=>b.onclick=()=>{d.close();void openOperation(this.c,b.dataset.code,{record:r,refs:this.refs,defaults:{tezgah:id},onDone:()=>this.load()});});}
 async jobMenu(id,person){const r=this.refs.IS.find(x=>idOf(x)===id);const ops=['IS.SIRALADIM','IS.DEVRETTIM','IS.DEGISTIRDIM','IS.BAGLANTI_DUZELTTIM','IS.SURE_EKLEDIM','IS.IPTAL_ETTIM'].filter(k=>this.can(k));const d=modal(r?.islem??'İş İşlemleri',`<div class="mini-menu"><button type="button" data-inspect-job>Ayrıntı ve Dosyalar</button>${this.can('IS.TANIMLADIM')?'<button type="button" data-change-job>Değişiklik</button>':''}${ops.map(code=>`<button type="button" data-code="${code}">${esc(OPERATIONS[code].title)}</button>`).join('')}</div>`);d.querySelector('[data-inspect-job]')?.addEventListener('click',()=>{d.close();void this.inspect('IS',id);});d.querySelector('[data-change-job]')?.addEventListener('click',()=>{d.close();void this.newFrom('IS',id,true);});d.querySelectorAll('[data-code]').forEach(b=>b.onclick=()=>{d.close();void openOperation(this.c,b.dataset.code,{record:r,refs:this.refs,defaults:{kisi:person,kimden:person},actingFor:person,onDone:()=>this.load()});});}
 bindDrag(){document.querySelectorAll('tr[data-kind=IS]').forEach(row=>{row.draggable=true;row.ondragstart=e=>e.dataTransfer.setData('application/irp-job',JSON.stringify({id:row.dataset.id}));row.ondblclick=()=>void this.operation('IS.ATADIM',row.dataset.id,'IS');});document.querySelectorAll('[data-job]').forEach(row=>row.ondragstart=e=>e.dataTransfer.setData('application/irp-job',JSON.stringify({id:row.dataset.job,person:row.dataset.person})));document.querySelectorAll('[data-drop-person]').forEach(target=>{target.ondragover=e=>{e.preventDefault();target.classList.add('drop-over');};target.ondragleave=()=>target.classList.remove('drop-over');target.ondrop=async e=>{e.preventDefault();target.classList.remove('drop-over');try{const data=JSON.parse(e.dataTransfer.getData('application/irp-job'));const person=target.dataset.dropPerson,r=this.refs.IS.find(x=>idOf(x)===data.id),code=data.person&&data.person!==person?'IS.DEVRETTIM':data.person===person?'IS.SIRALADIM':'IS.ATADIM';const count=arr(this.value('LISTE',person)?.isler).length;await openOperation(this.c,code,{record:r,refs:this.refs,defaults:{kisi:person,sira:count+1,kimden:data.person,kime:person,kime_sira:count+1,yeni_sira:1},onDone:()=>this.load()});}catch(ex){toast(ex.message,true);}};});}
 newTask(){return {ad:'',nereye:'PROJE',onay_gerekli:true,dosya_gerekli:false,on_kosul:[],oncelik:'NORMAL',olcum:'ZAMAN',onay_beklet:false};}
 bindAssignment(){const host=document.querySelector('#assignment-host');if(!host)return;if(!this.draftRows.length){this.draftIndex=-1;host.innerHTML=`<section class="assignment-empty">${button('＋ Yeni İş','assign-add',{},'primary')}</section>`;return;}this.draftIndex=Math.max(0,Math.min(this.draftIndex,this.draftRows.length-1));const r=this.draftRows[this.draftIndex];const itemSchema=structuredClone(this.c.schemas['GOREV.ATADIM'].girdi_semasi.properties.gorevler.items);const kept=['ad','is_tanimi','nereye','proje','etap','parca_kodu','kisi','teslim_tarihi','teslim_saati','zaman_degeri','zorluk','oncelik','on_kosul','dosya_gerekli','onay_gerekli','onaylayan','sorun_kaynakli','planlanan_baslangic','planlanan_bitis','degisiklik'];itemSchema.properties=Object.fromEntries(kept.filter(k=>itemSchema.properties[k]).map(k=>[k,itemSchema.properties[k]]));itemSchema.properties.olcum={enum:['ZAMAN','SAAT']};itemSchema.properties.birim={type:'string'};itemSchema.properties.tezgah={type:'string'};itemSchema.properties.onay_beklet={type:'boolean'};itemSchema.properties.kategori={type:'string'};FIELD_LABELS.olcum='Ölçüm';const total=this.draftRows.reduce((a,x)=>a+Number(x.zaman_degeri??0),0);
  host.innerHTML=`<div class="assignment"><aside class="assignment-list"><div class="assignment-list-header">Bu Atamadaki İşler <span class="badge">${this.draftRows.length}</span></div><div id="assignment-items">${this.draftRows.map((x,i)=>`<button type="button" class="assignment-item ${i===this.draftIndex?'active':''}" data-action="assign-select" data-index="${i}"><small class="draft-project">${esc(x.proje?this.name(x.proje):x.nereye==='PROJE_DISI'?'Proje Dışı':'Proje Seçilmedi')}</small><strong>${esc(x.ad||'Yeni İş')}</strong><small class="draft-meta">${esc(this.name(x.kisi))} · ${date(x.teslim_tarihi)} · ${hours(x.zaman_degeri)}</small></button>`).join('')}</div><div class="assignment-controls">${button('＋ Yeni İş','assign-add',{},'small')}${button('Çoğalt','assign-copy',{},'small')}${button('Sil','assign-remove',{},'small')}</div></aside><div class="assignment-editor"><h2>İşin Tanımı ve Ataması</h2><div id="task-editor"></div>${r.girdi_dosyalari?.length?`<div class="notice">Önceki teslimin dosyaları: ${r.girdi_dosyalari.map(id=>button('Dosyayı Aç','file',{id},'small')).join(' ')}</div>`:''}</div></div><div class="assignment-summary"><span><strong>${this.draftRows.length}</strong> iş · <strong id="assign-total">${hours(total)}</strong> planlanan emek</span><span class="muted">Atamadan önce bütün işleri ve teslim koşullarını kontrol edin.</span>${button('Özeti Kontrol Et','assign-review',{},'primary')}</div>`;
  bindForm(host.querySelector('#task-editor'),()=>assignmentSchema(itemSchema,r),r,{client:this.c,code:'GOREV.ATADIM',refs:this.refs,taskRows:this.draftRows,taskRowIndex:this.draftIndex},()=>{host.querySelectorAll('.draft-project')[this.draftIndex].textContent=r.nereye==='PROJE_DISI'?'Proje Dışı':r.proje?this.name(r.proje):'Proje Seçilmedi';host.querySelectorAll('.assignment-item strong')[this.draftIndex].textContent=r.ad||'Yeni İş';host.querySelectorAll('.assignment-item .draft-meta')[this.draftIndex].textContent=this.name(r.kisi)+' · '+date(r.teslim_tarihi)+' · '+hours(r.zaman_degeri);host.querySelector('#assign-total').textContent=hours(this.draftRows.reduce((a,x)=>a+Number(x.zaman_degeri??0),0));});headingCase(host);
 }
 adjustDraftLinks(at,delta){for(const row of this.draftRows)row.on_kosul=(row.on_kosul??[]).flatMap(h=>{if(typeof h!=='object')return [h];const index=h.satir-1;if(delta<0&&index===at)return [];return [{satir:h.satir+(index>=at?delta:0)}];});}
 async reviewAssignment(){
  if(!this.draftRows.length){toast('Önce Yeni İş ile bir iş hazırlayın.',true);return;}
  const issues=draftLinkIssues(this.draftRows);
  if(issues.length){this.draftIndex=issues[0].index;this.bindAssignment();showValidation(document.querySelector('#task-editor'),issues.filter(i=>i.index===this.draftIndex));toast(issues[0].message,true);return;}
  for(let i=0;i<this.draftRows.length;i++){
   const row=this.draftRows[i],mode=row.olcum??'ZAMAN',code=mode==='SAAT'?'IS.TANIMLADIM':'GOREV.ATADIM',key=mode==='SAAT'?'isler':'gorevler';
   const payload=assignmentPayload(this.draftRows,[],mode),localIndex=this.draftRows.slice(0,i).filter(r=>(r.olcum??'ZAMAN')===mode).length,item=payload[key][localIndex],schema=operationSchema(code,this.c.schemas).properties[key].items;
   for(const issue of validationIssues(item,schema))issues.push({...issue,index:i,path:issue.path==='islem'?'ad':issue.path==='tahmini_sure_dk'?'zaman_degeri':issue.path});
   for(const [field,message]of [['ad','İşin adı gerekli.'],...(row.nereye==='PROJE'?[['proje','Proje seçilmeli.']]:[]),...(mode==='SAAT'?[['birim','Ekip havuzunun birimi seçilmeli.']]:[])])if(!row[field])issues.push({index:i,path:field,message});
   if(row.nereye==='PROJE'&&(row.etap===undefined||row.etap===''))issues.push({index:i,path:'etap',message:'Etap veya Etap Dışı seçin.'});
   if(mode==='SAAT'&&!(Number(row.zaman_degeri)>0))issues.push({index:i,path:'zaman_degeri',message:'Tahmini Süre sıfırdan büyük olmalı.'});
  }
  if(issues.length){this.draftIndex=issues[0].index;this.bindAssignment();showValidation(document.querySelector('#task-editor'),issues.filter(i=>i.index===this.draftIndex));toast(issues[0].message,true);return;}

  showValidation(document.querySelector('#task-editor'),[]);
  // Uyarı satırları iki eylem grubunda yeniden numaralanır.
  const warning=(await this.c.read('ATAMA_UYARILARI',null,{satirlar:this.draftRows},true)).deger??[];
  const completed=new Set();const payloads=['ZAMAN','SAAT'].map(mode=>({mode,g:assignmentPayload(this.draftRows,warning,mode)}));
  const workload=this.draftRows.some(r=>r.olcum!=='SAAT')?(await this.c.read('ATAMA_YUKU',null,{satirlar:this.draftRows.filter(r=>r.olcum!=='SAAT')},true)).deger??{haftalar:[],uyarilar:[]}:{haftalar:[],uyarilar:[]};
  const d=modal('Atama Özeti',`${warning.length?`<div class="notice warn">${warning.map(w=>`İş ${w.satir}: ${esc(w.metin??w.uyari??label(w.kural??w.kod))}`).join('<br>')}</div>`:''}${assignmentReview(this.draftRows,id=>this.name(id))}<details class="assignment-capacity"><summary>Haftalık Yük ve Kapasite</summary>${table([{label:'Çalışan',render:r=>esc(this.name(r.kisi))},{label:'Hafta',render:r=>date(r.bas)+' – '+date(r.bit)},{label:'Bu Atamanın Haftalık Payı',render:r=>hours(r.yeni)},{label:'Mevcut Haftalık Yük',render:r=>hours(r.yuk)},{label:'Toplam / Kapasite',render:r=>hours(Number(r.yeni)+Number(r.yuk))+' / '+hours(r.kapasite)}],workload.haftalar)}<p class="capacity-note">Emek, bugünden teslim gününe kadar normal mesai saatleriyle orantılı dağılır. Haftalık yük, kalan iş süresi değildir.</p>${workload.uyarilar.map(r=>`<p class="notice warn">${esc(r.kisi?this.name(r.kisi)+': ':'')}${r.geciken?`${r.geciken} gecikmiş açık görev var. Önceki günlere düşen emek bu haftanın yükü değildir.`:'Bu tarihe kadar uygun mesai günü yok; yeni emek haftalara dağıtılamadı.'}</p>`).join('')}</details>${this.draftRows.some(x=>x.olcum==='SAAT')?'<div class="notice">Saat ölçümlü işler seçili ekibin havuzuna bırakılır; çalışan atamasını ekip lideri yapar.</div>':''}<div class="form-error"></div><div class="form-footer"><button class="btn" data-back>Geri Dön</button><button class="btn primary" data-assign>Ata</button></div>`,{wide:true});
  d.addEventListener('close',()=>{if(completed.size&&this.page==='assign')this.bindAssignment();});
  d.querySelector('[data-back]').onclick=()=>d.close();
  let assigning=false;d.querySelector('[data-assign]').onclick=async e=>{if(assigning)return;assigning=true;e.target.disabled=true;d.querySelector('[data-close]').disabled=true;d.querySelector('[data-back]').disabled=true;try{
   for(const {mode,g} of payloads){if(completed.has(mode))continue;if(!g[mode==='SAAT'?'isler':'gorevler'].length)continue;const result=await this.c.confirmed(mode==='SAAT'?'IS.TANIMLADIM':'GOREV.ATADIM',g);completed.add(mode);this.draftRows=remainingDrafts(this.draftRows,mode);this.draftIndex=0;if(!operationComplete(result)){d.close();toast(operationMessage(result)+(this.draftRows.length?' Kalan işler henüz gönderilmedi.':''),operationTone(result));await this.load();return;}}
   d.close();this.draftIndex=0;toast('İşler atandı.');try{await this.load();}catch{toast('İşler atandı. Görünüm yenilenemedi.');}
  }catch(ex){d.querySelector('.form-error').textContent=ex.message;e.target.disabled=false;d.querySelector('[data-close]').disabled=false;d.querySelector('[data-back]').disabled=false;}finally{assigning=false;}};
  return d;
 }
}
